inline const LookField* find_look_field(LookSubject s, const char* name) {
    for (const LookField& f : kLookFields)
        if (f.subject == s && std::strcmp(f.name, name) == 0) return &f;
    return nullptr;
}

inline const LookValue* find_look_value(const LookField& f, int32_t code) {
    for (int32_t i = 0; i < f.n_values; ++i)
        if (f.values[i].code == code) return &f.values[i];
    return nullptr;
}

